export function checkIfAppendLimitRequired(sql: string, limit: number = 0) {
  const trimmedSql = sql.trim()

  // Remove a single trailing semicolon (and surrounding whitespace) so that a
  // well-formed single statement isn't mistaken for multiple statements.
  const withoutTrailingSemicolon = trimmedSql.replace(/;\s*$/, '')

  const appendAutoLimit =
    // Only append when a positive limit has been requested
    limit > 0 &&
    // Must be a SELECT statement
    /^select/i.test(withoutTrailingSemicolon) &&
    // Must not already contain a LIMIT clause
    !/\blimit\b/i.test(withoutTrailingSemicolon) &&
    // Must be a single statement (no additional semicolons remaining)
    !withoutTrailingSemicolon.includes(';') &&
    // Must not contain line comments, which could hide additional clauses
    !withoutTrailingSemicolon.includes('--')

  return { appendAutoLimit }
}

/**
 * Removes any trailing semicolons from the given SQL and appends a LIMIT clause,
 * ensuring the resulting string ends with exactly one semicolon.
 */
export function suffixWithLimit(sql: string, limit: number) {
  const cleanedSql = sql.replace(/;+\s*$/, '')
  return `${cleanedSql} limit ${limit};`
